const ABLITERATION_DEFAULT_API_BASE_URL = 'https://api.abliteration.ai/v1';
const ABLITERATION_DEFAULT_API_KEY_ENVAR = 'ABLIT_KEY';
const ABLITERATION_API_BASE_URL_ENVAR = 'ABLIT_API_BASE_URL';

/**
 * Returns the value if it is a non-empty string, otherwise undefined.
 * Empty strings are treated as "unset" so resolution falls through to the
 * next priority level.
 */
function nonEmpty(value: string | undefined): string | undefined {
  return value && value.trim() !== '' ? value : undefined;
}

/**
 * Provider for the Abliteration AI service. It speaks an OpenAI-compatible
 * chat completions API but is fully self-contained: it never falls back to
 * OpenAI credentials, organization, or base URL.
 */
export class AbliterationProvider extends OpenAiChatCompletionProvider {
  // The apiBaseUrl explicitly passed via constructor config (if any). Kept
  // separate from the default so environment overrides can take precedence
  // when no explicit value was provided.
  private readonly explicitApiBaseUrl?: string;

  constructor(modelName: string, options: ProviderOptions = {}) {
    const inputConfig = options.config ?? {};
    super(modelName, {
      ...options,
      config: {
        ...inputConfig,
        apiBaseUrl: nonEmpty(inputConfig.apiBaseUrl) ?? ABLITERATION_DEFAULT_API_BASE_URL,
        apiKeyEnvar: inputConfig.apiKeyEnvar || ABLITERATION_DEFAULT_API_KEY_ENVAR,
        showThinking: inputConfig.showThinking ?? false,
      },
    });
    this.explicitApiBaseUrl = nonEmpty(inputConfig.apiBaseUrl);
  }

  id(): string {
    return `abliteration:${this.modelName}`;
  }

  toString(): string {
    return `[Abliteration Provider ${this.modelName}]`;
  }

  toJSON() {
    return {
      provider: 'abliteration' as const,
      model: this.modelName,
      config: {
        apiBaseUrl: this.config.apiBaseUrl as string,
        apiKey: undefined,
        apiKeyEnvar: this.config.apiKeyEnvar as string,
        showThinking: this.config.showThinking as boolean,
      },
    };
  }

  /**
   * Resolves the API base URL. Priority (highest wins):
   *   1. config.apiBaseUrl passed to the constructor
   *   2. providerOptions.env.ABLIT_API_BASE_URL
   *   3. process.env.ABLIT_API_BASE_URL
   *   4. the built-in default
   * Empty strings are treated as unset at every level.
   */
  getApiUrl(): string {
    return (
      nonEmpty(this.explicitApiBaseUrl) ||
      nonEmpty((this.env as Record<string, string | undefined> | undefined)?.[
        ABLITERATION_API_BASE_URL_ENVAR
      ]) ||
      nonEmpty(process.env[ABLITERATION_API_BASE_URL_ENVAR]) ||
      ABLITERATION_DEFAULT_API_BASE_URL
    );
  }

  /**
   * Resolves the API key. Priority (highest wins):
   *   1. config.apiKey
   *   2. providerOptions.env.ABLIT_KEY
   *   3. process.env.ABLIT_KEY
   * Never falls back to OPENAI_API_KEY.
   */
  getApiKey(): string | undefined {
    const envar = this.config.apiKeyEnvar || ABLITERATION_DEFAULT_API_KEY_ENVAR;
    return (
      nonEmpty(this.config.apiKey) ||
      nonEmpty((this.env as Record<string, string | undefined> | undefined)?.[envar]) ||
      nonEmpty(process.env[envar])
    );
  }

  /** Abliteration has no organization concept; never use OPENAI_ORGANIZATION. */
  getOrganization(): undefined {
    return undefined;
  }

  async callApi(
    prompt: string,
    context?: CallApiContextParams,
    callApiOptions?: CallApiOptionsParams,
  ): Promise<ProviderResponse> {
    const apiKey = this.getApiKey();
    if (!apiKey) {
      throw new Error(
        'API key is not set. Set the ABLIT_KEY environment variable or add `apiKey` to the provider config.',
