    }

    const { body } = await this.getOpenAiBody(prompt, context, callApiOptions);
    const url = `${this.getApiUrl()}/chat/completions`;

    logger.debug('[Abliteration] Calling API', { url, body });

    let data: any;
    let status: number;
    let statusText: string;
    let cached = false;
